#pragma once

//==============================================================================
// felitronics::appkit::brand — THE TEXT FACE, as opposed to the wordmark face in BrandAssets.h.
//
// Michroma is a display face: it sets the wordmark and the fixed labels we write ourselves, and it
// has no Cyrillic and no Greek — measured on its cmap, 0 and 3, the three mathematical. That is
// fine for words we choose and fatal for words we do not: a preset name is typed by a player, and
// half a name falling back to the host's font mid-word is worse than all of it in a plain one.
//
// This is the face for those. Science Gothic (OFL), pinned at wdth 146 / wght 300 and cut to the
// twelve languages the family's sites and products offer — EN DE UK RU CS ES FR IT PL PT RO TR.
//
// WHY THOSE COORDINATES. Science Gothic carries a width axis (50–200), which is what made it the
// candidate: at wdth 146 its average uppercase advance sits within 0.3% of Michroma's, so the two
// faces stand side by side on a toolbar without the layout shifting. wght 300 puts its stem at
// 0.0895 em against Michroma's 0.094 — within 5%, close enough that the pair reads as one voice.
// It was chosen over 211 other Google Fonts families with Cyrillic by measuring both numbers on
// every one of them; the runners-up matched the width and missed the stroke by four to seven times.
//
// A SEPARATE HEADER on purpose: 78 kB of base64 is not a cost a product should pay for including
// the brand kit. Include this one only where text in an unknown language is actually set.
//
// Science Gothic is licensed under the SIL Open Font License 1.1 (assets/ScienceGothic-OFL.txt and
// THIRD_PARTY_NOTICES.md); the notice declares no Reserved Font Name. The original variable font
// and the regeneration commands live in assets/ — see assets/README.md.
//==============================================================================

#include <juce_graphics/juce_graphics.h>

namespace felitronics::appkit::brand
{

namespace assets
{
    // Split into chunks because MSVC refuses a string literal over 64 kB — including one made by
    // concatenating adjacent literals.
    inline const char* const textFaceBase64[] = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        nullptr
    };
}

/** The text face, decoded once per process. Null only if the embedded data is corrupt. */
inline juce::Typeface::Ptr textTypeface()
{
    static const juce::Typeface::Ptr face = []
    {
        juce::MemoryOutputStream b64;
        for (const char* const* c = assets::textFaceBase64; *c != nullptr; ++c)
            b64 << *c;

        juce::MemoryOutputStream ttf;
        if (! juce::Base64::convertFromBase64 (ttf, b64.toString()))
            return juce::Typeface::Ptr {};

        return juce::Typeface::createSystemTypefaceFor (ttf.getData(), ttf.getDataSize());
    }();
    return face;
}

/** The text face at a size, with the host's own as the last resort — a decode that failed must
    still leave the product with readable words. */
inline juce::Font textFont (float height)
{
    if (auto tf = textTypeface())
        return juce::Font (juce::FontOptions().withHeight (height).withTypeface (tf));

    return juce::Font (juce::FontOptions (height));
}

} // namespace felitronics::appkit::brand
